"""Helper functions."""

import logging
import shutil
import tempfile
import typing

from jsilib import _utils, helpers

from . import _globals
from . import exc as aio_exc
from .interface import IReactor, IStream, IStreamReader, IStreamWriter, ITemporaryDirectory

__all__ = export = _utils.ExportList(['repeat_until_returns'])

logger = logging.getLogger(_globals.LOGGER_NAME)

# For backwards compatibility
# TODO: Remove in next major version update
repeat_until_returns = helpers.repeat_until_returns


@export
async def write_all(stream: IStreamWriter, data: bytes):
    """Writes all provided ``data`` to the ``stream``.

    If writing to given stream fails for some reason, then this function throws
    :exc:`IStreamWriter.WriteError` exception.
    """
    written = 0
    while written < len(data):
        count = await stream.write(data[written:])
        if count == 0:
            raise aio_exc.StreamOverflowError()
        written += count


@export
async def read_all(stream: IStreamReader, count: int) -> bytes:
    """Read exactly ``count`` bytes from given ``stream``.

    If it is not possible to read exactly ``count`` bytes, then
    :exc:`StreamError` exception is raised. Otherwise, a bytes object of
    ``count`` length is returned.
    """
    out = b''
    read = 0
    while read < count:
        chunk = await stream.read(count - read)
        if not chunk:
            raise aio_exc.StreamEOFError()
        read += len(chunk)
        out += chunk
    return out


@export
async def read_until_eof(stream: IStreamReader, chunk_size: int = 4096) -> bytes:
    """Read from a *stream* until an EOF is reached.

    Returns bytes read from the *stream* or raises :exc:`StreamError` in case
    of error.

    :param stream:
        Stream to read from

    :param chunk_size:
        Maximal size of data (in bytes) to be read by a single read operation.
    """
    out = b''
    while True:
        chunk = await stream.read(chunk_size)
        if not chunk:
            return out
        out += chunk


@export
async def copy_all(src: IStreamReader, dest: IStreamWriter, count: int, chunk_size: int = 4096):
    """Copy exactly *count* bytes from *src* to *dest*.

    This works similarly to :func:`read_all` except the fact that bytes read
    from *src* are written to the *dest*, not returned. This function will
    raise :exc:`StreamError` if either of these events happen:

        * there are no more bytes in *src*,
        * reading from *src* fails,
        * writing to *dest* fails.

    :param src:
        Stream to read from

    :param dest:
        Stream to write to

    :param chunk_size:
        Maximal number of bytes to read from *src* per single read call.
    """
    while count > 0:
        chunk = await src.read(min(count, chunk_size))
        if not chunk:
            raise aio_exc.StreamEOFError()
        await dest.write(chunk)
        count -= len(chunk)


@export
async def read_until(stream: IStreamReader, terminator: bytes, include_terminator: bool = False) -> bytes:
    """Read from a given *stream* until *terminator* is founc.

    Returns received bytes or raises :exc:`StreamError` if reading failed.

    :param stream:
        Stream to read from

    :param terminator:
        Awaited ending bytes

    :param include_terminator:
        If set to ``True``, then *terminator* will be included in the output.
        Otherwise it will be stripped from the output.
    """
    data = b''
    while not data.endswith(terminator):
        chunk = await stream.read(1)
        if not chunk:
            raise aio_exc.StreamEOFError()
        data += chunk
    if include_terminator:
        return data
    return data[:-len(terminator)]


@export
async def open_file(reactor: IReactor, path: str, mode: str = 'r') -> IStream:
    """Asynchronously open file at given *path* using provided *mode* and
    return :class:`IStream` instance that represents that opened file.

    :param reactor:
        Reactor to be used

    :param path:
        File path

    :param mode:
        File open mode.

        Currently supported are **w** (for write-only mode) and **r** (for
        read-only mode). File is always opened in binary mode, as
        :class:`IStream` interface operates on bytes.
    """

    async def do_open(mode):
        try:
            return await reactor.run_blocking(open, path, mode)
        except FileNotFoundError as e:
            raise aio_exc.IOError(f"File not found: {path}", original_exc=e)

    if mode == 'r':
        return _FileStream(reactor, await do_open('rb'))
    if mode == 'w':
        return _FileStream(reactor, await do_open('wb'))
    raise ValueError(f'unsupported file open mode: {mode}')


class _FileStream(IStream):

    def __init__(self, reactor: IReactor, fd: typing.BinaryIO):
        self._reactor = reactor
        self._fd = fd

    def is_closed(self) -> bool:
        return self._fd.closed

    async def close(self):
        await self._reactor.run_blocking(self._fd.close)

    async def read(self, count: int) -> bytes:
        if self.is_closed():
            raise aio_exc.StreamClosedError()
        return await self._reactor.run_blocking(self._fd.read, count)

    async def write(self, data: bytes) -> int:
        if self.is_closed():
            raise aio_exc.StreamClosedError()
        return await self._reactor.run_blocking(self._fd.write, data)


@export
async def create_temporary_directory(reactor: IReactor) -> ITemporaryDirectory:
    """Asynchronously create temporary directory and return a handle to that
    directory.

    The handle contains :attr:`ITemporaryDirectory.path` that points to a newly
    created temporary directory. Once :meth:`ITemporaryDirectory.close` is
    called on a returned handle, then corresponding temporary directory with
    all files inside will be removed.

    :param reactor:
        Reactor to be used
    """
    return _TemporaryDirectory(reactor, await reactor.run_blocking(tempfile.mkdtemp))


class _TemporaryDirectory(ITemporaryDirectory):

    def __init__(self, reactor: IReactor, tmpdir: str):
        self._tmpdir = tmpdir
        self._reactor = reactor
        self._closed = False

    @property
    def __fspath__(self) -> str:
        return self._tmpdir

    @property
    def path(self) -> str:
        return self._tmpdir

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            await self._reactor.run_blocking(shutil.rmtree, self._tmpdir)
